WITH base AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, SUBSTRING(status, 1, 4) AS status_prefix FROM subscriptions WHERE customer_id IS NOT NULL) SELECT customer_id, MAX(monthly_fee) FILTER (WHERE plan = 'premium') AS premium_max_monthly_fee, COUNT(*) FILTER (WHERE plan = 'standard') AS standard_rows, COUNT_IF(plan = 'basic') AS basic_events, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM base GROUP BY customer_id ORDER BY premium_max_monthly_fee DESC
